-- ════════════════════════════════════════════════════════════════════
-- Update the FINAL 16 email templates still on Old Design → CRM Design
-- Date: 2026-09-17
--
-- This migration covers ALL remaining templates that were still showing
-- "Old Design" in the email template audit. After running this, EVERY
-- email template in the database will use the unified CRM design with
-- the MyZipVault brand palette.
--
-- Templates updated (16 total):
--   1. candidate_invite             9.  profile_nudge_75
--   2. checklist_reminder           10. reengage_30d
--   3. checklist_request            11. welcome_candidate
--   4. email_verification           12. welcome_day0
--   5. existing_candidate_checklist 13. welcome_day1
--   6. password_reset               14. welcome_day3
--   7. profile_nudge_25             15. welcome_day7
--   8. profile_nudge_50             16. welcome_day14_reengage
--
-- Design system (consistent with all other CRM templates):
--   - Ivory background #F7F3E8
--   - White card #FFFFFF with #E5DFCF border, 16px radius
--   - Teal header #174A43 with terracotta eyebrow #D98F78
--   - Charcoal body text #263633
--   - Sage secondary text #5C6B66
--   - Teal CTA button #174A43
--   - Footer: "HIPAA Aligned · 256-bit Encryption · BAA Available"
--
-- Run in Supabase SQL Editor. Idempotent — safe to re-run.
-- ════════════════════════════════════════════════════════════════════

BEGIN;

-- ─────────────────────────────────────────────────────────────────────
-- 1. candidate_invite — recruiter sends job invite to candidate
-- ─────────────────────────────────────────────────────────────────────
UPDATE "EmailTemplate" SET
  subject = '{{recruiter_name}} invited you to apply: {{job_title}}',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;letter-spacing:-0.5px;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">Job Invitation</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hello {{candidate_name}},</p><p style="margin:0 0 16px;color:#5C6B66;"><strong style="color:#174A43;">{{recruiter_name}}</strong> from <strong style="color:#174A43;">{{recruiter_company}}</strong> thought you''d be a great fit for:</p><div style="background-color:#F7F3E8;border-left:3px solid #D98F78;padding:16px 20px;border-radius:6px;margin:20px 0;"><div style="font-size:17px;font-weight:700;color:#174A43;margin-bottom:4px;">{{job_title}}</div><div style="font-size:14px;color:#5C6B66;">{{job_location}} · {{job_pay}}</div></div><p style="margin:0 0 16px;color:#5C6B66;">{{recruiter_message}}</p><div style="text-align:center;margin:28px 0;"><a href="{{accept_link}}" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">View Invitation</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">You received this invitation because a recruiter identified you as a strong match.<br>HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'candidate_invite';

-- ─────────────────────────────────────────────────────────────────────
-- 2. checklist_reminder — reminder to complete checklist
-- ─────────────────────────────────────────────────────────────────────
UPDATE "EmailTemplate" SET
  subject = 'Reminder: Complete your checklist for {{job_title}}',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;letter-spacing:-0.5px;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">Checklist Reminder</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hello {{candidate_name}},</p><p style="margin:0 0 16px;color:#5C6B66;">This is a friendly reminder that your checklist for <strong style="color:#174A43;">{{job_title}}</strong> is still incomplete. You''ve finished <strong style="color:#D98F78;">{{completed_count}} of {{total_count}}</strong> items.</p><div style="background-color:#F7F3E8;border-radius:10px;padding:20px;margin:20px 0;"><div style="font-size:13px;color:#5C6B66;margin-bottom:8px;">Progress</div><div style="background-color:#E5DFCF;border-radius:6px;height:10px;overflow:hidden;"><div style="background-color:#174A43;height:100%;width:{{progress_percent}}%;border-radius:6px;"></div></div></div><p style="margin:0 0 16px;color:#5C6B66;">Completing your checklist is required before you can be submitted to this position.</p><div style="text-align:center;margin:28px 0;"><a href="{{checklist_link}}" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Continue Checklist</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'checklist_reminder';

-- ─────────────────────────────────────────────────────────────────────
-- 3. checklist_request — initial request to complete checklist
-- ─────────────────────────────────────────────────────────────────────
UPDATE "EmailTemplate" SET
  subject = 'Action required: Complete your checklist for {{job_title}}',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;letter-spacing:-0.5px;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">Checklist Request</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hello {{candidate_name}},</p><p style="margin:0 0 16px;color:#5C6B66;"><strong style="color:#174A43;">{{recruiter_name}}</strong> has requested that you complete a compliance checklist for the position <strong style="color:#174A43;">{{job_title}}</strong> at <strong>{{employer_name}}</strong>.</p><div style="background-color:#F7F3E8;border-left:3px solid #D98F78;padding:16px 20px;border-radius:6px;margin:20px 0;"><div style="font-size:14px;color:#5C6B66;margin-bottom:4px;">Position</div><div style="font-size:16px;font-weight:600;color:#174A43;">{{job_title}}</div><div style="font-size:13px;color:#5C6B66;margin-top:6px;">{{total_count}} items · Approx. {{estimated_time}}</div></div><p style="margin:0 0 16px;color:#5C6B66;">Please complete this checklist at your earliest convenience. Once submitted, your recruiter will be notified automatically.</p><div style="text-align:center;margin:28px 0;"><a href="{{checklist_link}}" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Start Checklist</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'checklist_request';

-- ─────────────────────────────────────────────────────────────────────
-- 4. email_verification — verify email address
