UPDATE "EmailTemplate" SET
  subject = 'Verify your email address',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;letter-spacing:-0.5px;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">Verify Email</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hello {{user_name}},</p><p style="margin:0 0 16px;color:#5C6B66;">Please verify your email address to activate your MyZipVault account. This link will expire in <strong style="color:#174A43;">24 hours</strong>.</p><div style="text-align:center;margin:28px 0;"><a href="{{verification_link}}" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Verify My Email</a></div><p style="margin:0 0 16px;color:#8B9994;font-size:13px;">If you didn''t create an account, you can safely ignore this email.</p></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'email_verification';

-- ─────────────────────────────────────────────────────────────────────
