UPDATE "EmailTemplate" SET
  subject = 'New opportunity: {{job_title}} at {{employer_name}}',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;letter-spacing:-0.5px;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">New Opportunity</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hello {{candidate_name}},</p><p style="margin:0 0 16px;color:#5C6B66;">A new position matches your verified profile. Since your credentials are already on file, applying takes just one click.</p><div style="background-color:#F7F3E8;border-left:3px solid #D98F78;padding:16px 20px;border-radius:6px;margin:20px 0;"><div style="font-size:17px;font-weight:700;color:#174A43;margin-bottom:4px;">{{job_title}}</div><div style="font-size:14px;color:#5C6B66;">{{employer_name}} · {{job_location}}</div><div style="font-size:14px;color:#5C6B66;margin-top:4px;">{{job_pay}}</div></div><p style="margin:0 0 16px;color:#5C6B66;">A short checklist ({{total_count}} items) is required before submission. Most candidates finish in {{estimated_time}}.</p><div style="text-align:center;margin:28px 0;"><a href="{{checklist_link}}" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Start Checklist</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
