-- 14. welcome_day3 — how MyZipVault works
-- ─────────────────────────────────────────────────────────────────────
UPDATE "EmailTemplate" SET
  subject = 'How MyZipVault works — meet your recruiter',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;letter-spacing:-0.5px;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">How It Works</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hi {{candidate_name}},</p><p style="margin:0 0 16px;color:#5C6B66;">Wondering how MyZipVault works? Here''s the short version:</p><ol style="margin:0 0 16px;color:#263633;padding-left:20px;"><li style="margin-bottom:8px;"><strong style="color:#174A43;">You create a profile</strong> — upload your credentials, license, and resume</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">We verify your credentials</strong> — usually within 24 hours</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">You browse open jobs</strong> — filter by specialty, location, pay</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">You apply with one click</strong> — your verified profile goes straight to the recruiter</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">The recruiter reaches out</strong> — directly, no middleman</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">You get hired</strong> — sign your contract electronically on MyZipVault</li></ol><p style="margin:0 0 16px;color:#5C6B66;">Unlike traditional agencies, MyZipVault is a <strong style="color:#174A43;">marketplace</strong> — multiple recruiters compete for your placement, so you get the best offers.</p><p style="margin:0 0 16px;color:#5C6B66;"><strong style="color:#D98F78;">Pro tip:</strong> Complete your profile to 100% to rank higher in recruiter searches. Profiles with photos, full work history, and verified credentials get <strong style="color:#174A43;">3x more recruiter views</strong>.</p><div style="text-align:center;margin:28px 0;"><a href="https://my-zip-vault.vercel.app/settings" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Complete My Profile</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'welcome_day3';

-- ─────────────────────────────────────────────────────────────────────
-- 15. welcome_day7 — interview tips
-- ─────────────────────────────────────────────────────────────────────
UPDATE "EmailTemplate" SET
  subject = '7 tips to ace your next healthcare interview',
  body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"></head><body style="margin:0;padding:0;background-color:#F7F3E8;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#263633;line-height:1.6;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background-color:#F7F3E8;"><tr><td align="center" style="padding:32px 16px;"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width:600px;width:100%;background-color:#FFFFFF;border-radius:16px;overflow:hidden;box-shadow:0 1px 3px rgba(23,74,67,0.06);border:1px solid #E5DFCF;"><tr><td style="background-color:#174A43;padding:28px 32px;text-align:center;"><div style="font-family:Georgia,serif;font-size:24px;font-weight:700;color:#FFFFFF;letter-spacing:-0.5px;">MyZipVault</div><div style="font-size:11px;font-weight:600;color:#D98F78;letter-spacing:2.5px;text-transform:uppercase;margin-top:6px;">Interview Tips</div></td></tr><tr><td style="padding:36px;font-size:15px;color:#263633;"><p style="margin:0 0 16px;">Hi {{candidate_name}},</p><p style="margin:0 0 16px;color:#5C6B66;">You''ve been on MyZipVault for a week — hopefully you''ve applied to a few jobs by now. When a recruiter reaches out, here''s how to nail the interview:</p><ol style="margin:0 0 16px;color:#263633;padding-left:20px;"><li style="margin-bottom:8px;"><strong style="color:#174A43;">Research the facility</strong> — know their specialty, bed count, and recent news</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">Prepare clinical scenarios</strong> — expect "tell me about a time you handled a difficult patient"</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">Have your credentials ready</strong> — license, BLS/ACLS, immunization records</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">Ask smart questions</strong> — nurse-to-patient ratio, orientation length, EMR system</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">Know your worth</strong> — check market rates for your specialty/location on our salary guide</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">Negotiate</strong> — most facilities have 8–12% wiggle room on bill rate</li><li style="margin-bottom:8px;"><strong style="color:#174A43;">Follow up</strong> — send a thank-you email within 24 hours</li></ol><div style="background-color:#F7F3E8;border-left:3px solid #D98F78;padding:14px 20px;border-radius:6px;margin:20px 0;font-style:italic;color:#5C6B66;font-size:14px;">"I applied to 3 travel nurse contracts on MyZipVault, got calls from 2 recruiters within 48 hours, and was offered both. I picked the higher-paying one and started 2 weeks later."<br><br>— <strong style="color:#174A43;">Sarah K., ICU RN</strong></div><div style="text-align:center;margin:28px 0;"><a href="https://my-zip-vault.vercel.app/browse-jobs" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Browse Open Jobs</a></div></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'welcome_day7';

