;">+8%</strong></div></div><p style="margin:0 0 16px;color:#5C6B66;">It takes 2 minutes to update your profile and start applying.</p><div style="text-align:center;margin:28px 0;"><a href="https://my-zip-vault.vercel.app/login" style="background-color:#174A43;color:#FFFFFF;padding:14px 32px;border-radius:10px;text-decoration:none;font-weight:600;display:inline-block;font-size:15px;">Log In Now</a></div><p style="margin:0 0 16px;color:#8B9994;font-size:13px;">If you have feedback or need help, just reply to this email — we read every reply.</p></td></tr><tr><td style="padding:0 36px 20px;"><table width="100%" style="border-top:1px solid #E5DFCF;padding-top:20px;"><tr><td style="font-size:12px;color:#8B9994;text-align:center;">HIPAA Aligned · 256-bit Encryption · BAA Available</td></tr></table></td></tr></table></td></tr></table></body></html>'
WHERE template_key = 'welcome_day14_reengage';

COMMIT;

-- ════════════════════════════════════════════════════════════════════
-- Verification — should show ALL templates as CRM Design after running
-- ════════════════════════════════════════════════════════════════════
SELECT
  template_key,
  CASE
    WHEN body LIKE '%#174A43%' AND body LIKE '%#F7F3E8%' AND body LIKE '%#D98F78%' THEN '✅ CRM Design'
    ELSE '❌ Old Design'
  END AS design_status
FROM "EmailTemplate"
ORDER BY template_key;
